const rates = {
  USD: 1.0,
  EUR: 0.92,
  GBP: 0.79,
  JPY: 155.2,
  CAD: 1.38
};

const amountInput = document.getElementById('amount-input');
const fromCurrency = document.getElementById('from-currency');
const toCurrency = document.getElementById('to-currency');
const swapBtn = document.getElementById('swap-btn');
const rateDisplay = document.getElementById('rate-display');
const resultDisplay = document.getElementById('result-display');
const historyList = document.getElementById('history-list');

const STORAGE_KEY = 'currency_converter_history_v1';

function calculateConversion() {
  const amount = parseFloat(amountInput.value) || 0;
  const from = fromCurrency.value;
  const to = toCurrency.value;

  const rate = (rates[to] / rates[from]);
  const result = (amount * rate).toFixed(2);

  rateDisplay.textContent = `1 ${from} = ${rate.toFixed(4)} ${to}`;
  resultDisplay.textContent = `${result} ${to}`;

  if (amount > 0) {
    saveToHistory(`${amount} ${from} → ${result} ${to}`);
  }
}

function saveToHistory(entry) {
  try {
    const history = JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
    const updated = [entry, ...history.filter(h => h !== entry)].slice(0, 5);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
    renderHistory();
  } catch (e) {
    console.warn('LocalStorage error:', e);
  }
}

function renderHistory() {
  try {
    const history = JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
    historyList.innerHTML = '';
    history.forEach(item => {
      const li = document.createElement('li');
      li.textContent = item;
      historyList.appendChild(li);
    });
  } catch (e) {
    console.warn('Failed to render history:', e);
  }
}

function swapCurrencies() {
  const temp = fromCurrency.value;
  fromCurrency.value = toCurrency.value;
  toCurrency.value = temp;
  calculateConversion();
}

amountInput.addEventListener('input', calculateConversion);
fromCurrency.addEventListener('change', calculateConversion);
toCurrency.addEventListener('change', calculateConversion);
swapBtn.addEventListener('click', swapCurrencies);

// Initial execution
calculateConversion();
renderHistory();

:root {
  --bg-color: #0f172a;
  --card-bg: #1e293b;
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --primary: #38bdf8;
  --primary-hover: #0ea5e9;
  --border-color: #334155;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}

.converter-card {
  background-color: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: 1rem;
  width: 100%;
  max-width: 480px;
  padding: 2rem;
  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.5);
}

.converter-header {
  text-align: center;
  margin-bottom: 1.5rem;
}

.app-title {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary);
  margin-bottom: 0.25rem;
}

.app-subtitle {
  font-size: 0.875rem;
  color: var(--text-muted);
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  margin-bottom: 1.25rem;
}

.form-group label {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-muted);
}

.input-field, .select-field {
  background-color: #0b1120;
  border: 1px solid var(--border-color);
  border-radius: 0.5rem;
  color: var(--text-main);
  padding: 0.75rem 1rem;
  font-size: 1rem;
  outline: none;
  transition: border-color 0.2s;
}

.input-field:focus, .select-field:focus {
  border-color: var(--primary);
}

.currency-row {
  display: flex;
  align-items: flex-end;
  gap: 0.75rem;
}

.flex-1 {
  flex: 1;
}

.swap-button {
  background: #0b1120;
  border: 1px solid var(--border-color);
  color: var(--primary);
  border-radius: 0.5rem;
  width: 2.75rem;
  height: 2.75rem;
  font-size: 1.25rem;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  margin-bottom: 1.25rem;
  transition: background-color 0.2s, border-color 0.2s;
}

.swap-button:hover {
  background-color: #1e293b;
  border-color: var(--primary);
}

.result-container {
  background-color: #0b1120;
  border: 1px solid var(--border-color);
  border-radius: 0.75rem;
  padding: 1.25rem;
  text-align: center;
  margin: 1.5rem 0;
}

.rate-info {
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-bottom: 0.25rem;
}

.converted-amount {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--text-main);
}

.converter-footer {
  border-top: 1px solid var(--border-color);
  padding-top: 1.25rem;
}

.history-title {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-muted);
  margin-bottom: 0.5rem;
}

.history-list {
  list-style: none;
  font-size: 0.8125rem;
  color: var(--text-muted);
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
}

.history-list li {
  display: flex;
  justify-content: space-between;
  padding: 0.25rem 0;
  border-bottom: 1px dashed rgba(255, 255, 255, 0.05);
}
